extern alias Production;
extern alias DesktopRecovered;
extern alias CadRecovered;
using GemvisionGeometry.Helpers;
using System.Globalization;
namespace ReuseSmoke;
public static class Checks {
public static string Run(){ int cases=0;using var sr=new StreamReader(typeof(Checks).Assembly.GetManifestResourceStream("golden.txt")!); foreach(var line in sr.ReadToEnd().Split('\n')){if(!line.Contains('|'))continue;var f=line.Trim().Split('|');int n=int.Parse(f[0]);double u=double.Parse(f[1],CultureInfo.InvariantCulture);var expected=f[2].Split(',').Select(v=>double.Parse(v,CultureInfo.InvariantCulture)).ToArray();GNurbsMath.AllBernstein(n,u,out var actual);if(actual.Length!=expected.Length)throw new Exception("Length mismatch");for(int i=0;i<actual.Length;i++)if(Math.Abs(actual[i]-expected[i])>1e-14)throw new Exception("Original binary golden mismatch");if(Math.Abs(actual.Sum()-1)>1e-12)throw new Exception("Basis sum");cases++;}if(cases!=16)throw new Exception("Missing golden cases");var vector=new GemvisionGeometry.Geometry.GVector3D(3,4,0);if(vector.Length!=5)throw new Exception("Vector length");
var cross=GemvisionGeometry.Geometry.GVector3D.CrossProduct(GemvisionGeometry.Geometry.GVector3D.XAxis,GemvisionGeometry.Geometry.GVector3D.YAxis);if(cross.X!=0||cross.Y!=0||cross.Z!=1)throw new Exception("Cross product");
var compressionReport=new List<string>();foreach(var text in new[]{"", "CounterSketch portable compression",new string('x',100000)}){try{var input=System.Text.Encoding.UTF8.GetBytes(text);var packed=DesktopRecovered::GV.CounterSketch.Studio.ZipIt.ZlibStream.CompressBuffer(input);System.Console.WriteLine($"ZLIB case length={input.Length} packed={packed.Length} prefix={Convert.ToHexString(packed.Take(8).ToArray())}");using var ms=new MemoryStream(packed);using var zs=new System.IO.Compression.ZLibStream(ms,System.IO.Compression.CompressionMode.Decompress);using var output=new MemoryStream();zs.CopyTo(output);if(!output.ToArray().SequenceEqual(input))throw new Exception("Recovered->BCL zlib mismatch");using var target=new MemoryStream();using(var writer=new System.IO.Compression.ZLibStream(target,System.IO.Compression.CompressionLevel.Optimal,true))writer.Write(input);var decoded=DesktopRecovered::GV.CounterSketch.Studio.ZipIt.ZlibStream.UncompressBuffer(target.ToArray());if(!decoded.SequenceEqual(input))throw new Exception("BCL->recovered zlib mismatch");compressionReport.Add($"{text.Length}:interchange-pass,compressed-bytes={packed.Length}");}catch(Exception error){compressionReport.Add($"{text.Length}:FAIL:{error.GetType().Name}");}}
if(CadRecovered::GV.CounterSketch.Shared.Utilities.Helpers.GemCaratHelper.GetSpecificGravityForMaterial(CadRecovered::GV.CounterSketch.Shared.GemMaterial.Diamond)!=3.52)throw new Exception("Diamond density");
int domainMaterials=0;foreach(var material in Enum.GetValues<Production::GV.CounterSketch.Shared.GemMaterial>()){var expected=CadRecovered::GV.CounterSketch.Shared.Utilities.Helpers.GemCaratHelper.GetSpecificGravityForMaterial((CadRecovered::GV.CounterSketch.Shared.GemMaterial)(int)material);var actual=Production::GV.CounterSketch.Shared.Utilities.Helpers.GemCaratHelper.GetSpecificGravityForMaterial(material);if(expected!=actual)throw new Exception("Production material mapping mismatch");domainMaterials++;}
if(domainMaterials!=114)throw new Exception("Production material catalog count mismatch");
var graphContractResult=GraphContractChecks.Assertions.Run();
return $"PASS {cases} original-binary golden Bernstein cases; vector length/cross; diamond density; production domain {domainMaterials} material comparisons; {graphContractResult}; compression probe (non-gating): {string.Join(";",compressionReport)}";}
}